        orgPredicate(issueBlockers.orgId, orgId),
        eq(issueBlockers.issueId, issueId),
        eq(issueBlockers.blockerId, blockerId),
      ),
    )
    .get();
  return row ? toIssueDependency(row) : null;
}

/** Stores the link, or leaves an existing one untouched, and returns what is stored. */
export async function insertDependency(
  link: IssueDependency,
): Promise<IssueDependency> {
