cat > src/server/services/issue-dependency-service.ts <<'EOF'
/**
 * "Blocked by" links between issues: recording and removing them, the completion gate that stops blocked work being marked done, and the notification sent when a blocker closes and releases its dependents.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, requireFound, notify, subscribe
 */
import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived, isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueDependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { issueResource, requireFound } from "./_support";
import { notify } from "./notification-service";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue, IssueDependency, IssueStatus } from "@/types/issue";
import type { Actor } from "@/types/member";

export interface BlockerLinkInput {
  readonly orgId: OrgId;
  readonly issueId: IssueId;
  readonly blockerId: IssueId;
}

/** Raised by the completion gate when a `done` change still has open blockers. */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly blockerIds: readonly IssueId[]) {
    super(`Issue cannot be completed while ${blockerIds.length} blocker(s) are open`);
    this.name = "IssueBlockedError";
  }
}

/** Raised when a link would make an issue block itself, directly or through a chain. */
export class BlockerCycleError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: IssueId,
    readonly blockerId: IssueId,
  ) {
    super(`Issue ${issueId} cannot be blocked by ${blockerId}: the link would form a cycle`);
    this.name = "BlockerCycleError";
  }
}

function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

/**
 * Records "`issueId` is blocked by `blockerId`". Adding a link that already
 * exists returns the stored link instead of writing a duplicate.
 */
export async function addBlocker(
  actor: Actor,
  input: BlockerLinkInput,
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const blocked = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );
  assertCan(actor, "issue:update", issueResource(blocked));
  assertNotArchived("Issue", blocked.id, blocked);
  assertNotArchived("Issue", blocker.id, blocker);

  if (input.issueId === input.blockerId) {
    throw new BlockerCycleError(input.issueId, input.blockerId);
  }

  const existing = await issueDependencyRepo.findDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
  if (existing) return existing;

  // The new link closes a cycle exactly when the issue is already reachable
  // from the blocker by following "blocked by" links.
  if (await reachesThroughBlockers(input.orgId, input.blockerId, input.issueId)) {
    throw new BlockerCycleError(input.issueId, input.blockerId);
  }

  return issueDependencyRepo.insertDependency({
    orgId: input.orgId,
    issueId: input.issueId,
    blockerId: input.blockerId,
    createdBy: actor.userId,
    createdAt: toIsoTimestamp(new Date()),
  });
}

/** Deletes the link. Resolves `false` when there was no link to remove. */
export async function removeBlocker(
  actor: Actor,
  input: BlockerLinkInput,
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const blocked = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(blocked));

  return issueDependencyRepo.deleteDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
}

/** The live blockers of `issueId`, open or closed, ordered by issue number. */
export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return issueDependencyRepo.listBlockerIssues(orgId, issueId);
}

/**
 * The completion gate. Called by every path that moves an issue to `done`, and
 * throws before anything is written when a blocker is still open.
 */
export async function assertNotBlocked(
  orgId: OrgId,
  issueId: IssueId,
): Promise<void> {
  const blockerIds = await issueDependencyRepo.listOpenBlockerIds(orgId, issueId);
  if (blockerIds.length > 0) {
    throw new IssueBlockedError(blockerIds);
  }
}

/** True when `target` is `from` itself or lies upstream of it in the blocker graph. */
async function reachesThroughBlockers(
  orgId: OrgId,
  from: IssueId,
  target: IssueId,
): Promise<boolean> {
  const seen = new Set<IssueId>();
  const pending: IssueId[] = [from];

  while (pending.length > 0) {
    const current = pending.pop() as IssueId;
    if (current === target) return true;
    if (seen.has(current)) continue;
    seen.add(current);

    pending.push(...(await issueDependencyRepo.listBlockerIds(orgId, current)));
  }

  return false;
}

/**
 * Notifies the assignee of each issue that `blockerId` was holding back, once
 * that issue has no open blocker left. Skips issues that are archived, already
 * closed or unassigned; the notification fan-out applies the recipient's
 * preferences and skips the actor.
 */
async function releaseBlockedIssues(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: UserId | null,
): Promise<void> {
  const blockedIds = await issueDependencyRepo.listBlockedIssueIds(orgId, blockerId);

  for (const blockedId of blockedIds) {
    const blocked = await issueRepo.findIssueById(orgId, blockedId);
    if (!blocked || isArchived(blocked) || isClosedStatus(blocked.status)) continue;
    if (blocked.assigneeId === null) continue;

    const open = await issueDependencyRepo.listOpenBlockerIds(orgId, blocked.id);
    if (open.length > 0) continue;

    await notify(orgId, "issue_unblocked", [blocked.assigneeId], {
      title: "An issue is unblocked",
      body: `Issue ${blocked.id} is no longer blocked`,
      href: `/issues/${blocked.id}`,
      actorId,
    });
  }
}

/**
 * Reacts to a blocker closing: a status move from open to `done`/`canceled`,
 * or an archive of a blocker that was still open. Closed-to-closed changes do
 * not notify, and removing a link never does.
 */
export function registerIssueDependencyListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", async (payload) => {
      if (isClosedStatus(payload.from) || !isClosedStatus(payload.to)) return;
      await releaseBlockedIssues(payload.orgId, payload.issueId, payload.actorId);
    }),
    subscribe("issue.archived", async (payload) => {
      // Archiving leaves the status alone, so the stored status is the one the
      // blocker had when it was archived.
      const archived = await issueRepo.findIssueById(payload.orgId, payload.issueId);
      if (!archived || isClosedStatus(archived.status)) return;
      await releaseBlockedIssues(payload.orgId, payload.issueId, payload.actorId);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}
