    expect(got[0]!.actorId).toBe(t.actors.member.userId);

    // closed -> closed does nothing
    await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: b2.id, status: "done" });
    expect(await notifsFor(t.userIds.admin)).toHaveLength(1);
  });

  it("archive of an open blocker notifies; archive of a closed blocker does not; mute respected", async () => {
    const dep = await mk("Dep2", t.userIds.owner);
