    await preferenceRepo.upsertPreference({ orgId: t.org.id, userId: t.userIds.admin, kind: "issue_unblocked", inApp: false, email: false, digestOnly: false } as any);
    const dep4 = await mk("Dep4", t.userIds.admin);
    const b4 = await mk("B4");
    await depService.addBlocker(t.actors.member, { orgId: t.org.id, issueId: dep4.id, blockerId: b4.id });
    await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: b4.id, status: "done" });
    expect(await notifsFor(t.userIds.admin)).toHaveLength(1);
  });
});
